const digits='٠١٢٣٤٥٦٧٨٩';
function normalize(value){return String(value||'').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/[٠-٩]/g,d=>String(digits.indexOf(d))).toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,'');}
function grams(value){const s=normalize(value);if(s.length<3)return new Set([s]);const set=new Set();for(let i=0;i<=s.length-3;i++)set.add(s.slice(i,i+3));return set;}
function dice(a,b){const A=grams(a),B=grams(b);if(!A.size||!B.size)return 0;let same=0;for(const g of A)if(B.has(g))same++;return 2*same/(A.size+B.size);}
function existingVerbal(){const out=[];for(const value of Object.values(window)){if(!Array.isArray(value))continue;for(const item of value){if(!item||typeof item!=='object'||!Array.isArray(item.options))continue;if((item.subject||'')!=='qudurat-verbal')continue;if(!(item.q||item.question))continue;out.push(item);}}return out;}
const existing=existingVerbal();
const accepted=[];
for(const [id,sourceTimestamp,category,level,q,options,answer,explain,passage=''] of rows){
  const qn=normalize(q), pn=normalize(passage), composite=`${passage} ${q}`.trim();
  const duplicate=existing.some(item=>{
    const iq=String(item.q||item.question||''), ip=String(item.passage||'');
    const iqn=normalize(iq), ipn=normalize(ip);
    if(qn===iqn && (!pn||!ipn||pn===ipn))return true;
    const base=Math.min(normalize(composite).length,normalize(`${ip} ${iq}`).length);
    if(base>=55 && dice(composite,`${ip} ${iq}`)>=0.94)return true;
    if(Math.min(qn.length,iqn.length)>=35 && dice(q,iq)>=0.955)return true;
    return false;
  });
  if(duplicate)continue;
  const item={id:`upvid-verbal-20260810-${id}`,area:'exams',family:'qudurat',subject:'qudurat-verbal',category,level,q,options,answer,explain,source,sourceTimestamp};
  if(passage)item.passage=passage;
  accepted.push(item);existing.push(item);
}
window.NEON_UPLOADED_VIDEO_VERBAL_TAJMIAT_20260810=accepted;
